DROP TABLE IF EXISTS `dou_admin_log`;
CREATE TABLE `dou_admin_log` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `created_at` datetime DEFAULT NULL,
  `result` tinyint(1) NOT NULL DEFAULT '0' COMMENT '操作结果',
  `details` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '详情',
  `admin_id` mediumint(8) unsigned NOT NULL DEFAULT '0' COMMENT '管理员ID',
  `action` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '操作类型',
  `module` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '路由模块',
  `ip` varchar(45) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '操作IP',
  PRIMARY KEY (`id`),
  KEY `admin_id` (`admin_id`),
  KEY `module` (`module`),
  KEY `ip` (`ip`),
  KEY `created_at` (`created_at`),
  KEY `action` (`action`(191))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `dou_aftersale`;
CREATE TABLE `dou_aftersale` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '售后单ID',
  `aftersale_sn` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '售后单号',
  `order_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '订单ID',
  `user_id` mediumint(8) unsigned NOT NULL DEFAULT '0' COMMENT '会员ID',
  `type` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'refund_only',
  `currency_code` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '售后单货币代码',
  `currency_rate` decimal(18,8) NOT NULL DEFAULT '1.00000000' COMMENT '售后单汇率',
  `currency_decimal` tinyint(3) unsigned NOT NULL DEFAULT '2' COMMENT '售后单价格小数位数',
  `reason` text COLLATE utf8mb4_unicode_ci COMMENT '售后原因',
  `handled_at` datetime DEFAULT NULL,
  `admin_id` int(10) unsigned NOT NULL DEFAULT '0',
  `status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `created_at` datetime DEFAULT NULL,
  `expired_at` datetime DEFAULT NULL,
  `closed_at` datetime DEFAULT NULL,
  `version` smallint(5) unsigned NOT NULL DEFAULT '0',
  `apply_amount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `approved_amount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `refunded_amount` decimal(10,2) NOT NULL DEFAULT '0.00',
  PRIMARY KEY (`id`),
  KEY `idx_order` (`order_id`),
  KEY `idx_user` (`user_id`),
  KEY `idx_status_expired` (`status`,`expired_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `dou_aftersale_item`;
CREATE TABLE `dou_aftersale_item` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `aftersale_id` int(10) unsigned NOT NULL DEFAULT '0',
  `order_id` int(10) unsigned NOT NULL DEFAULT '0',
  `order_item_id` int(10) unsigned NOT NULL DEFAULT '0',
  `item_id` mediumint(8) unsigned NOT NULL DEFAULT '0',
  `quantity` smallint(5) unsigned NOT NULL DEFAULT '1',
  `amount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `reason` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  KEY `idx_aftersale` (`aftersale_id`),
  KEY `idx_order_item` (`order_item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `dou_aftersale_log`;
CREATE TABLE `dou_aftersale_log` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `aftersale_id` int(10) unsigned NOT NULL DEFAULT '0',
  `from_status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `to_status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `action` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `operator_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `operator_id` int(10) unsigned NOT NULL DEFAULT '0',
  `note` text COLLATE utf8mb4_unicode_ci,
  `attachment_token` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `ip` varchar(45) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_aftersale` (`aftersale_id`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

