DROP TABLE IF EXISTS `dou_aftersale_return`;
CREATE TABLE `dou_aftersale_return` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `aftersale_id` int(10) unsigned NOT NULL DEFAULT '0',
  `shipping_company` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `tracking_no` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `shipped_at` datetime DEFAULT NULL,
  `received_at` datetime DEFAULT NULL,
  `receive_note` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `reject_reason` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_aftersale` (`aftersale_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `dou_area`;
CREATE TABLE `dou_area` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '区域ID',
  `parent_id` int(11) NOT NULL DEFAULT '0' COMMENT '父级区域ID',
  `lang` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'zh_cn',
  `name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '区域名称',
  `iso_code_2` varchar(2) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'ISO两位国家代码',
  `iso_code_3` varchar(3) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'ISO三位国家代码',
  `sort` tinyint(1) unsigned NOT NULL DEFAULT '50' COMMENT '排序',
  PRIMARY KEY (`id`),
  KEY `idx_parent` (`parent_id`),
  KEY `idx_lang_parent` (`lang`,`parent_id`)
) ENGINE=InnoDB AUTO_INCREMENT=8309 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

