DROP TABLE IF EXISTS `dou_article`;
CREATE TABLE `dou_article` (
  `id` mediumint(8) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `category_id` smallint(5) NOT NULL DEFAULT '0' COMMENT '分类ID',
  `operator_type` enum('admin','work','open') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'admin' COMMENT '创建者类型',
  `operator_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '创建者ID',
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标题',
  `slug` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'URL标识',
  `content` longtext COLLATE utf8mb4_unicode_ci COMMENT '正文内容',
  `image` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '缩略图',
  `metadata` longtext COLLATE utf8mb4_unicode_ci COMMENT '扩展字段(JSON，默认语言)',
  `click` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '点击数',
  `keywords` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'SEO关键词',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT 'SEO描述',
  `sort` smallint(5) unsigned NOT NULL DEFAULT '50' COMMENT '排序',
  `status` tinyint(1) unsigned NOT NULL DEFAULT '1' COMMENT '状态:1启用,0禁用',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_slug` (`slug`),
  KEY `idx_operator` (`operator_type`,`operator_id`),
  KEY `idx_category` (`category_id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO dou_article VALUES('1','1','admin','0','Article Title Demo','','<p>How to Operate a Cross - Border E - Commerce Business</p><p>In today&#39;s globalized world, cross - border e - commerce has become a booming industry. However, successfully operating a cross - border e - commerce business requires careful planning and strategic execution.</p><p>1. Market Research</p><p>Before diving into cross - border e - commerce, it is crucial to conduct thorough market research. Identify the target markets and understand the local consumer preferences, cultural differences, and market trends. For example, in some countries, consumers may prefer certain colors or styles of products, while in others, the focus may be on functionality or affordability. Researching the local competition is also essential. Analyze what products are already available, what prices they are sold at, and what the strengths and weaknesses of your competitors are. This information will help you position your products effectively and identify potential gaps in the market that you can fill.</p><p>2. Product Selection</p><p>Choosing the right products is a key factor in the success of your cross - border e - commerce business. Select products that have a high demand in your target market but are not overly saturated. Consider products that are unique or have a competitive advantage in terms of quality, design, or functionality. It is also important to ensure that the products comply with the local regulations and standards of the target countries. For instance, some countries have strict safety or environmental regulations for certain types of products. Additionally, think about the logistics and shipping aspects. Products that are lightweight and have a high value - to - weight ratio are generally easier and more cost - effective to ship internationally.</p>','pcrsl28.file',NULL,'0','','In today\'s globalized world, cross - border e - commerce has become a booming industry. However, successfully operating a cross - border e - commerce business requires careful planning and strategic execution.','50','1','2013-06-26 23:39:00');
