DROP TABLE IF EXISTS `dou_attribute`;
CREATE TABLE `dou_attribute` (
  `id` smallint(5) NOT NULL AUTO_INCREMENT COMMENT '属性ID',
  `module` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'product' COMMENT '所属模块',
  `category_id` smallint(5) NOT NULL DEFAULT '0' COMMENT '关联分类ID',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '属性名称',
  `type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'text' COMMENT '属性类型',
  `sort` tinyint(1) unsigned NOT NULL DEFAULT '50' COMMENT '排序',
  PRIMARY KEY (`id`),
  KEY `idx_attr_module_category` (`module`,`category_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

