DROP TABLE IF EXISTS `dou_attribute_value`;
CREATE TABLE `dou_attribute_value` (
  `id` mediumint(8) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `module` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'product' COMMENT '所属模块',
  `item_id` smallint(8) unsigned NOT NULL DEFAULT '0' COMMENT '商品ID',
  `att_id` smallint(8) unsigned NOT NULL DEFAULT '0' COMMENT '属性ID',
  `value` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '属性值',
  `type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'text' COMMENT '值类型',
  `image` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '图片',
  `remark` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '备注',
  `price_change` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '价格变动',
  PRIMARY KEY (`id`),
  KEY `idx_attr_value_item` (`module`,`item_id`),
  KEY `idx_attr_value_att` (`att_id`)
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

