DROP TABLE IF EXISTS `dou_brand`;
CREATE TABLE `dou_brand` (
  `id` mediumint(8) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '品牌名称',
  `class` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '品牌分组',
  `content` longtext COLLATE utf8mb4_unicode_ci COMMENT '品牌介绍',
  `image` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '品牌图片',
  `keywords` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'SEO关键词',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT 'SEO描述',
  `click` smallint(6) unsigned NOT NULL DEFAULT '0' COMMENT '点击数',
  `sort` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '排序',
  `status` tinyint(1) unsigned NOT NULL DEFAULT '1' COMMENT '状态:1启用,0禁用',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

