DROP TABLE IF EXISTS `dou_comment`;
CREATE TABLE `dou_comment` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `reply_id` int(10) NOT NULL DEFAULT '0' COMMENT '回复评论ID',
  `from` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'user' COMMENT '来源:user会员,admin管理员',
  `user_id` mediumint(8) unsigned NOT NULL DEFAULT '0' COMMENT '会员ID',
  `order_item_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '订单项ID',
  `module` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属模块',
  `item_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '内容ID',
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '评论内容',
  `star` tinyint(1) unsigned NOT NULL DEFAULT '5' COMMENT '星级评分',
  `anonymous` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '是否匿名:1是,0否',
  `if_show` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否显示:1是,0否',
  `if_read` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已读:1是,0否',
  `ip` varchar(45) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '提交IP',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_comment_item` (`module`,`item_id`,`if_show`),
  KEY `idx_comment_user` (`user_id`),
  KEY `idx_comment_order_item` (`order_item_id`),
  KEY `idx_comment_reply` (`reply_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `dou_config`;
CREATE TABLE `dou_config` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `name` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '配置名',
  `value` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '配置值',
  `type` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '表单控件类型',
  `box` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '可选项配置',
  `tab` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'main' COMMENT '所属选项卡',
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=83 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

