DROP TABLE IF EXISTS `dou_coupon`;
CREATE TABLE `dou_coupon` (
  `id` mediumint(8) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `name` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '优惠券名称',
  `coupon_sn` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '优惠券编号',
  `type` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'noauto' COMMENT '优惠券类型',
  `face_value` decimal(10,2) unsigned NOT NULL DEFAULT '100.00' COMMENT '面值',
  `max_discount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `limit_per_user` smallint(5) unsigned NOT NULL DEFAULT '1',
  `total_quantity` int(10) unsigned NOT NULL DEFAULT '0',
  `issued_quantity` int(10) unsigned NOT NULL DEFAULT '0',
  `is_stackable` tinyint(1) NOT NULL DEFAULT '0',
  `is_first_order_only` tinyint(1) NOT NULL DEFAULT '0',
  `condition` decimal(10,2) unsigned NOT NULL DEFAULT '100.00' COMMENT '使用条件金额',
  `scope_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'all',
  `scope_value` text COLLATE utf8mb4_unicode_ci,
  `start_at` datetime DEFAULT NULL,
  `end_at` datetime DEFAULT NULL,
  `brief` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '简介',
  `image` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '图片',
  `sort` tinyint(1) unsigned NOT NULL DEFAULT '50' COMMENT '排序',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态:1启用,0禁用',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

