DROP TABLE IF EXISTS `dou_coupon_log`;
CREATE TABLE `dou_coupon_log` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `user_id` mediumint(8) unsigned NOT NULL DEFAULT '0' COMMENT '会员ID',
  `coupon_id` mediumint(8) unsigned NOT NULL DEFAULT '0' COMMENT '优惠券ID',
  `claimed_at` datetime DEFAULT NULL,
  `used_at` datetime DEFAULT NULL,
  `order_sn` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `ip` varchar(45) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'IP',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_user_status` (`user_id`,`status`),
  KEY `idx_user_coupon` (`user_id`,`coupon_id`),
  KEY `idx_coupon_user` (`coupon_id`,`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `dou_data`;
CREATE TABLE `dou_data` (
  `id` smallint(5) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `parent_code` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '父级编码',
  `theme` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'default' COMMENT '所属主题',
  `data_group` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'common' COMMENT '数据分组',
  `data_item` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '关联项标识',
  `name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '名称',
  `code` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '编码',
  `image` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '图片',
  `text` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文本内容',
  `slots` longtext COLLATE utf8mb4_unicode_ci COMMENT '分区文本(JSON)',
  `link` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '跳转链接',
  `is_class` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否分组',
  `is_locked` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '是否锁定',
  `sort` tinyint(1) unsigned NOT NULL DEFAULT '50' COMMENT '排序',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_theme_code` (`theme`,`code`),
  KEY `idx_theme_group_item` (`theme`,`data_group`,`data_item`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

