DROP TABLE IF EXISTS `dou_email`;
CREATE TABLE `dou_email` (
  `id` mediumint(8) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `user_id` mediumint(8) unsigned NOT NULL DEFAULT '0' COMMENT '会员ID',
  `email` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '邮箱地址',
  `ip` varchar(15) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '订阅IP',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态:1已验证,0未验证',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `dou_favorites`;
CREATE TABLE `dou_favorites` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `user_id` mediumint(8) unsigned NOT NULL DEFAULT '0' COMMENT '会员ID',
  `module` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '收藏模块',
  `item_id` smallint(8) unsigned NOT NULL DEFAULT '0' COMMENT '收藏内容ID',
  `price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '收藏时价格(用于价格变动提醒)',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_user_item` (`user_id`,`module`,`item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `dou_file`;
CREATE TABLE `dou_file` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `uploader_type` enum('admin','user','work') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'admin' COMMENT '上传者类型',
  `uploader_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '上传者ID',
  `number` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '文件编号(唯一)',
  `file` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '文件路径',
  `module` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '所属模块',
  `item_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '关联内容ID',
  `type` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '文件类型',
  `size` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '文件大小(字节)',
  `thumb_size` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '缩略图大小(字节)',
  `original_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '原始文件名',
  `mime_type` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'MIME 类型',
  `storage_driver` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'local' COMMENT '存储驱动',
  `draft_token` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '草稿令牌',
  `draft_expire_at` datetime DEFAULT NULL,
  `status` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'owned' COMMENT '状态 draft/owned',
  `last_used_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `number` (`number`),
  KEY `idx_uploader_status_expire` (`uploader_type`,`uploader_id`,`status`,`draft_expire_at`),
  KEY `idx_draft_token` (`draft_token`)
) ENGINE=InnoDB AUTO_INCREMENT=105 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

