DROP TABLE IF EXISTS `dou_metadata`;
CREATE TABLE `dou_metadata` (
  `id` smallint(5) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `module` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '所属模块',
  `slug` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '字段标识',
  `label` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '显示名',
  `type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'input' COMMENT '字段类型',
  `options` text COLLATE utf8mb4_unicode_ci COMMENT '选项(每行一个)',
  `extensions` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'file 允许扩展名',
  `max_kb` int(10) unsigned NOT NULL DEFAULT '0' COMMENT 'file 大小上限KB(0=平台默认)',
  `required` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '是否必填',
  `limit` smallint(5) unsigned NOT NULL DEFAULT '0' COMMENT '多图/多选数量上限',
  `tip` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '字段提示',
  `sort` smallint(5) unsigned NOT NULL DEFAULT '50' COMMENT '排序',
  `status` tinyint(1) unsigned NOT NULL DEFAULT '1' COMMENT '状态:1启用,0禁用',
  PRIMARY KEY (`id`),
  UNIQUE KEY `module_slug` (`module`,`slug`),
  KEY `module_status` (`module`,`status`,`sort`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `dou_nav`;
CREATE TABLE `dou_nav` (
  `id` mediumint(8) NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `module` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '所属模块',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '导航名称',
  `icon` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '图标',
  `guide` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '关联目标(分类/页面ID)',
  `parent_id` smallint(5) NOT NULL DEFAULT '0' COMMENT '父级ID',
  `type` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '导航位置:middle中部,bottom底部',
  `status` tinyint(1) unsigned NOT NULL DEFAULT '1' COMMENT '状态:1显示,0隐藏',
  `sort` tinyint(3) unsigned NOT NULL DEFAULT '50' COMMENT '排序',
  PRIMARY KEY (`id`),
  KEY `idx_type_status` (`type`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

