DROP TABLE IF EXISTS `dou_order`;
CREATE TABLE `dou_order` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '订单ID',
  `order_sn` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `currency_code` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '下单时货币代码',
  `base_currency_code` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `currency_rate` decimal(18,8) NOT NULL DEFAULT '1.00000000' COMMENT '下单时汇率',
  `currency_decimal` tinyint(3) unsigned NOT NULL DEFAULT '2' COMMENT '下单时价格小数位数',
  `base_currency_decimal` tinyint(3) unsigned NOT NULL DEFAULT '2',
  `user_id` mediumint(8) unsigned NOT NULL DEFAULT '0' COMMENT '会员ID',
  `direct_user_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '直接推荐人ID',
  `indirect_user_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '间接推荐人ID',
  `mode` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'money' COMMENT '支付模式',
  `module` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '所属模块',
  `category_id` smallint(5) NOT NULL DEFAULT '0' COMMENT '分类ID',
  `contact_id` mediumint(8) unsigned NOT NULL DEFAULT '0' COMMENT '收货地址ID',
  `email` varchar(180) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '邮箱',
  `pay_id` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '支付方式标识',
  `shipping_id` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '配送方式标识',
  `tracking_no` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '物流单号',
  `shipping_fee` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '配送费',
  `currency_shipping_fee` decimal(12,2) NOT NULL DEFAULT '0.00',
  `item_amount` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '商品总金额',
  `currency_item_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `currency_coupon_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `order_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '订单总金额',
  `currency_order_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `order_point` smallint(8) unsigned NOT NULL DEFAULT '0' COMMENT '订单赠送积分',
  `direct_reward` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '直推奖励金额',
  `indirect_reward` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '间推奖励金额',
  `paid_at` datetime DEFAULT NULL,
  `shipped_at` datetime DEFAULT NULL,
  `closed_at` datetime DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `allow_aftersale` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '是否允许售后',
  `aftersale_status` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '售后状态',
  `allow_comment` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '是否允许评价',
  `item_link_status` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '商品链接状态',
  `parent_order_id` int(10) unsigned NOT NULL DEFAULT '0',
  `cancel_reason` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `refund_status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `buyer_message` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `seller_message` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `source` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'web',
  `status` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `created_at` datetime DEFAULT NULL,
  `wallet_paid` decimal(10,2) NOT NULL DEFAULT '0.00',
  `gateway_paid` decimal(10,2) NOT NULL DEFAULT '0.00',
  PRIMARY KEY (`id`),
  UNIQUE KEY `order_sn` (`order_sn`),
  KEY `idx_user_status` (`user_id`,`status`),
  KEY `idx_status_created` (`status`,`created_at`),
  KEY `idx_paid` (`paid_at`),
  KEY `idx_status_paid` (`status`,`paid_at`),
  KEY `idx_pay_id_status_paid` (`pay_id`,`status`,`paid_at`),
  KEY `idx_direct_user` (`direct_user_id`),
  KEY `idx_indirect_user` (`indirect_user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

