DROP TABLE IF EXISTS `dou_order_cart`;
CREATE TABLE `dou_order_cart` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `user_id` mediumint(8) unsigned NOT NULL DEFAULT '0' COMMENT '会员ID',
  `module` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属模块',
  `item_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '商品ID',
  `item_number` smallint(5) unsigned NOT NULL DEFAULT '1' COMMENT '数量',
  `attribute` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '属性值ID列表',
  PRIMARY KEY (`id`),
  KEY `idx_user_module_item` (`user_id`,`module`,`item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `dou_order_coupon`;
CREATE TABLE `dou_order_coupon` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `order_id` int(10) unsigned NOT NULL DEFAULT '0',
  `coupon_id` mediumint(8) unsigned NOT NULL DEFAULT '0',
  `coupon_log_id` int(10) unsigned NOT NULL DEFAULT '0',
  `amount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `currency_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_order` (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `dou_order_invoice`;
CREATE TABLE `dou_order_invoice` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `order_id` int(10) unsigned NOT NULL DEFAULT '0',
  `type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'personal',
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tax_no` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `email` varchar(180) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `is_issued` tinyint(1) NOT NULL DEFAULT '0',
  `issued_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_order` (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `dou_order_item`;
CREATE TABLE `dou_order_item` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `user_id` mediumint(8) unsigned NOT NULL DEFAULT '0' COMMENT '会员ID',
  `direct_user_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '直接推荐人ID',
  `indirect_user_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '间接推荐人ID',
  `order_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '订单ID',
  `module` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属模块',
  `category_id` smallint(5) NOT NULL DEFAULT '0' COMMENT '分类ID',
  `work_id` mediumint(8) unsigned NOT NULL DEFAULT '0' COMMENT '工作台ID',
  `item_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '商品ID',
  `name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品名称',
  `price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '原价',
  `sale_price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '实付价',
  `currency_price` decimal(12,2) NOT NULL DEFAULT '0.00',
  `currency_sale_price` decimal(12,2) NOT NULL DEFAULT '0.00',
  `currency_row_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `sale_price_type` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'original' COMMENT '价格类型',
  `point` smallint(8) unsigned NOT NULL DEFAULT '0' COMMENT '赠送积分',
  `direct_reward` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '直推奖励金额',
  `indirect_reward` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '间推奖励金额',
  `item_number` smallint(5) unsigned NOT NULL DEFAULT '1' COMMENT '数量',
  `attribute` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '属性值ID列表',
  `attribute_name` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '属性名称',
  `stock_lock` tinyint(1) unsigned NOT NULL DEFAULT '1' COMMENT '是否锁定库存',
  `aftersale` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '是否已申请售后',
  `comment` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '是否已评价',
  `order_status` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_cat_orderstatus` (`category_id`,`order_status`),
  KEY `idx_orderstatus_created` (`order_status`,`created_at`),
  KEY `idx_order` (`order_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

