DROP TABLE IF EXISTS `dou_order_refund`;
CREATE TABLE `dou_order_refund` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `refund_sn` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `order_id` int(10) unsigned NOT NULL DEFAULT '0',
  `aftersale_id` int(10) unsigned NOT NULL DEFAULT '0',
  `order_payment_id` int(10) unsigned NOT NULL DEFAULT '0',
  `channel` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `currency_code` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '退款单货币代码',
  `currency_rate` decimal(18,8) NOT NULL DEFAULT '1.00000000' COMMENT '退款单汇率',
  `currency_decimal` tinyint(3) unsigned NOT NULL DEFAULT '2' COMMENT '退款单价格小数位数',
  `amount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `base_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `raw_callback` text COLLATE utf8mb4_unicode_ci,
  `refunded_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_refund_sn` (`refund_sn`),
  KEY `idx_order` (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `dou_order_status_log`;
CREATE TABLE `dou_order_status_log` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `order_id` int(10) unsigned NOT NULL DEFAULT '0',
  `from_status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `to_status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `reason` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `operator_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `operator_id` int(10) unsigned NOT NULL DEFAULT '0',
  `ip` varchar(45) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_order` (`order_id`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `dou_page`;
CREATE TABLE `dou_page` (
  `id` mediumint(8) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `slug` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'URL标识',
  `parent_id` smallint(5) NOT NULL DEFAULT '0' COMMENT '父级ID',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '页面名称',
  `content` longtext COLLATE utf8mb4_unicode_ci COMMENT '页面内容',
  `metadata` longtext COLLATE utf8mb4_unicode_ci COMMENT '扩展字段(JSON，默认语言)',
  `keywords` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'SEO关键词',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT 'SEO描述',
  `editor_code` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '代码标识',
  `mode` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'editor' COMMENT '编辑模式',
  PRIMARY KEY (`id`),
  KEY `idx_slug` (`slug`),
  KEY `idx_parent` (`parent_id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO dou_page VALUES('1','about','0','About','<p><span><strong>About Us</strong></span></p><p><span>Founded in [Year], [Your Company Name] is a [industry/sector, e.g., leading technology, manufacturing, or consulting] company dedicated to [core mission, e.g., &quot;delivering innovative solutions for sustainable growth&quot;]. Headquartered in [Location], we serve [target market, e.g., global clients, local businesses, or specific industries] with a focus on [key value, e.g., quality, customer satisfaction, or cutting-edge technology].&nbsp;&nbsp;</span></p><p><span><br/></span></p><p><span><strong>Our Services/Products</strong></span></p><p><span>We specialize in:&nbsp;&nbsp;</span></p><p><span>- [Service/Product 1]&nbsp;&nbsp;</span></p><p><span>- [Service/Product 2]&nbsp;&nbsp;</span></p><p><span>- [Service/Product 3]&nbsp;&nbsp;</span></p><p><span><br/></span></p><p><span><strong>Why Choose Us?</strong></span></p><p><span>- **Expertise**: [X years] of experience in [industry].&nbsp;&nbsp;</span></p><p><span>- **Innovation**: Continuous investment in R&amp;D and technology.&nbsp;&nbsp;</span></p><p><span>- **Customer-Centric**: Tailored solutions to meet unique needs.&nbsp;&nbsp;</span></p><p><span>- [Add other strengths like sustainability, awards, etc.]&nbsp;&nbsp;</span></p><p><span><br/></span></p><p><span><strong>Our Vision</strong></span></p><p><span>To [long-term goal, e.g., &quot;be a global leader in smart solutions by 2030&quot;].&nbsp;&nbsp;</span></p><p><span><br/></span></p><p><span><strong>Contact Us</strong></span></p><p><span>[Email] | [Phone] | [Website] | [Social Media Links]&nbsp;&nbsp;</span></p><p><br/></p>',NULL,'','','','editor');
INSERT INTO dou_page VALUES('2','contact','0','Contact','<p><span style=\"text-wrap-mode: nowrap;\">Company name: Your Business Name Inc.</span></p><p><span style=\"text-wrap-mode: nowrap;\"><br/></span></p><p><span style=\"text-wrap-mode: nowrap;\">Phone number: +1 123-456-7891</span></p><p><span style=\"text-wrap-mode: nowrap;\"><br/></span></p><p><span style=\"text-wrap-mode: nowrap;\">Email: yourbusinessemail@domain.com</span></p><p><span style=\"text-wrap-mode: nowrap;\"><br/></span></p><p><span style=\"text-wrap-mode: nowrap;\">Address: 3 Industrial Pkwy S, Aurora Ontario L4G 3V9</span></p><p><br/></p>',NULL,'','','','editor');
