DROP TABLE IF EXISTS `dou_parameter`;
CREATE TABLE `dou_parameter` (
  `id` mediumint(8) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `name` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '参数键名',
  `lang` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '参数显示名',
  `value` text COLLATE utf8mb4_unicode_ci COMMENT '参数值',
  `cue` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '提示说明',
  `group` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'system' COMMENT '所属分组',
  `lock` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '是否锁定',
  `sort` tinyint(1) unsigned NOT NULL DEFAULT '50' COMMENT '排序',
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`),
  KEY `idx_group` (`group`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO dou_parameter VALUES('1','miniprogram_appid','AppID/小程序ID','','微信公众平台：mp.weixin.qq.com，“开发->开发设置”里获取','miniprogram','0','50');
INSERT INTO dou_parameter VALUES('2','miniprogram_appsecret','AppSecret/小程序密钥','','微信公众平台：mp.weixin.qq.com，“开发->开发设置”里获取','miniprogram','0','50');
INSERT INTO dou_parameter VALUES('3','miniprogram_pay_mch_id','微信支付商户号（如果没有使用到微信支付无需设置）','','微信商户平台：pay.weixin.qq.com，“账户中心->商户信息”里获取，另外需要在“产品中心-》AppID账号管理”将上面填写的AppID对应的小程序进行绑定','miniprogram','0','50');
INSERT INTO dou_parameter VALUES('4','miniprogram_pay_key','微信支付商户API密钥','','微信商户平台：pay.weixin.qq.com，“账户中心->API安全->设置APIv2密钥”里获取','miniprogram','0','50');
INSERT INTO dou_parameter VALUES('5','miniprogram_domain','站点网址（业务域名）','','请输入线上正式网址（以 / 结束），如果是本机调试可以输入本机地址，但正式发布小程序之前一定要改为线上网址','miniprogram','0','50');
INSERT INTO dou_parameter VALUES('6','login_mode','登录模式','email','输入email使用邮箱作为账号；输入mobile使用手机号作为账号（配套短信模块可以进行短信验证，请从DouPHP+安装）；输入weixin使用微信登录则无需注册（需配套微信登录插件或含微信登录功能的小程序）','user','0','50');
INSERT INTO dou_parameter VALUES('7','loginid_mode','微信登录唯一ID','unionid','如果输入openid则登录账号只在当前终端有效（这里的终端比如微信公众号、微信小程序、PC网页端），如果要各终端统一则输入unionid，这样各终端登录都作为同一个账号','user','0','50');
INSERT INTO dou_parameter VALUES('8','order_pay_timeout','未付款超时时间','60','设定未付款订单超时时间，超时后将自动取消订单，请输入数字（单位为分钟），默认为60分钟，未安装支付插件时此设置无效','order','0','50');
INSERT INTO dou_parameter VALUES('9','order_allow_aftersale_time','可申请售后期限','168','设定可申请售后的期限，请输入数字（单位为小时），完成订单后开始计算，默认为168小时（7天），未安装售后模块时此设置无效','order','0','50');
INSERT INTO dou_parameter VALUES('10','order_allow_comment_time','订单商品可评论期限','168','设定可订单商品可评论期限（超时将自动好评），请输入数字（单位为小时），完成订单后开始计算，默认为168小时（7天），未安装评论模块时此设置无效','order','0','50');

DROP TABLE IF EXISTS `dou_plugin`;
CREATE TABLE `dou_plugin` (
  `slug` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '插件标识',
  `name` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '插件名称',
  `config` text COLLATE utf8mb4_unicode_ci COMMENT '插件配置(序列化数组)',
  `plugin_group` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '插件分组',
  `allow_client` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ALL' COMMENT '允许的客户端',
  `description` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '插件描述',
  UNIQUE KEY `uniq_slug` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO dou_plugin VALUES('amazon','亚马逊账号登录','{\"client_id\":\"\",\"client_secret\":\"\"}','connect','ALL','接入 Login with Amazon，让网站支持亚马逊账号快速登录。需前往 https://developer.amazon.com/loginwithamazon/console/site/lwa/overview.html 注册应用并创建安全配置文件。');
INSERT INTO dou_plugin VALUES('express','Express','{\"fee\":\"10\",\"free\":\"0\"}','shipping','ALL','速度快，价格实惠，超重不加价。');
INSERT INTO dou_plugin VALUES('google','Google 登录','{\"client_id\":\"\",\"client_secret\":\"\"}','connect','ALL','接入 Google OAuth 2.0 一键登录，支持 Google 账号快速登录/注册，打通账号体系。');
INSERT INTO dou_plugin VALUES('lianlianpay','lianlianpay','{\"oid_partner\":\"\",\"rsa_private_key\":\"\",\"key\":\"\"}','payment','ALL','连连支付');
INSERT INTO dou_plugin VALUES('paypal','paypal','{\"seller_email\":\"\",\"currency_code\":\"USD\"}','payment','ALL','网上交易时，买家的交易资金直接打入卖家paypal账户，快速回笼交易资金。申请前必须拥有企业paypal账号。');

DROP TABLE IF EXISTS `dou_point`;
CREATE TABLE `dou_point` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `user_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '会员ID',
  `operator_type` enum('admin','user','work','system') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'user' COMMENT '操作者类型',
  `operator_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '操作者ID',
  `action` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '操作动作',
  `point` int(11) NOT NULL DEFAULT '0' COMMENT '变动积分',
  `total` int(11) NOT NULL DEFAULT '0' COMMENT '积分余额',
  `from` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '来源单号',
  `source_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'order_pay/sign/...',
  `source_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '关联表主键',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '备注',
  `ip` varchar(45) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'IP(兼容IPv6)',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_user` (`user_id`,`action`),
  KEY `idx_source` (`source_type`,`source_id`),
  KEY `idx_point_from` (`from`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `dou_product`;
CREATE TABLE `dou_product` (
  `id` mediumint(8) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `category_id` smallint(5) NOT NULL DEFAULT '0' COMMENT '分类ID',
  `operator_type` enum('admin','work') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'admin' COMMENT '创建者类型',
  `operator_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '创建者ID',
  `brand_id` mediumint(8) unsigned NOT NULL DEFAULT '0' COMMENT '品牌ID',
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品标题',
  `slug` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'URL标识',
  `price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '价格',
  `level_price` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '会员等级价(序列化数组)',
  `promote_price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '促销价',
  `promote_start_at` datetime DEFAULT NULL,
  `promote_end_at` datetime DEFAULT NULL,
  `stock` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '库存',
  `content` longtext COLLATE utf8mb4_unicode_ci COMMENT '商品详情',
  `image` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '缩略图',
  `metadata` longtext COLLATE utf8mb4_unicode_ci COMMENT '扩展字段(JSON，默认语言)',
  `model` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '型号',
  `point` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '赠送积分',
  `sales` mediumint(8) unsigned NOT NULL DEFAULT '0' COMMENT '销量',
  `keywords` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'SEO关键词',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT 'SEO描述',
  `sort` smallint(5) unsigned NOT NULL DEFAULT '50' COMMENT '排序',
  `status` tinyint(1) unsigned NOT NULL DEFAULT '1' COMMENT '状态:1启用,0禁用',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_slug` (`slug`),
  KEY `idx_operator` (`operator_type`,`operator_id`),
  KEY `idx_category` (`category_id`),
  KEY `idx_brand` (`brand_id`)
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO dou_product VALUES('1','5','admin','0','0','Product Name Demo','','3680.00','','0.00',NULL,NULL,'100','<p><span><strong>Product Overview&nbsp;</strong></span></p><p><span>We are honored to introduce our company’s latest product. This product has been meticulously developed and designed to meet consumer needs and deliver a high-quality experience. Below, we will detail its features, functions, advantages, and applications to provide you with a comprehensive understanding.&nbsp;&nbsp;</span></p><p><span><br/></span></p><p><span><strong>Product Features&nbsp;&nbsp;</strong></span></p><p><span>1. Innovative Design: Our product emphasizes innovation, combining a unique exterior design with advanced technological applications to ensure it stands out from the competition.&nbsp;&nbsp;</span></p><p><span>2. Outstanding Performance: We are committed to delivering exceptional performance. Whether in speed, stability, or longevity, our product offers an unparalleled experience.&nbsp;&nbsp;</span></p><p><span>3. High-Quality Materials: Premium materials are used in manufacturing to guarantee durability and reliability. The product boasts not only an appealing appearance but also superior functionality.&nbsp;&nbsp;</span></p><p><span>4. User-Centric Design: We prioritize user needs and habits, crafting designs that align with real-world usage. With intuitive operation and comprehensive features, it effortlessly meets user demands.&nbsp;&nbsp;</span></p><p><span><br/></span></p><p><span><strong>Product Functions</strong></span></p><p><span>Our product excels with the following features:&nbsp;&nbsp;</span></p><p><span>1. XXX Function: Leveraging cutting-edge technology, our product achieves the XXX function, providing users with convenient and efficient solutions.&nbsp;&nbsp;</span></p><p><span>2. XXX Function: Equipped with the XXX function, optimized design and superior performance ensure precise and stable user experiences.&nbsp;&nbsp;</span></p><p><span>3. XXX Function: Beyond the above, we’ve incorporated the XXX function to cater to diverse user needs and expectations.&nbsp;&nbsp;</span></p><p><span><br/></span></p><p><span><strong>Product Advantages</strong></span></p><p><span>1. High Cost-Effectiveness: Our product offers exceptional value in the market. While reasonably priced, it compromises neither quality nor performance.&nbsp;&nbsp;</span></p><p><span>2. Premium Service: We provide comprehensive after-sales support to ensure your satisfaction. From warranties to technical assistance, we stand by you at every step.&nbsp;&nbsp;</span></p><p><span>3. Reliability: User experience drives our rigorous quality testing, ensuring reliability and stability in every product.&nbsp;&nbsp;</span></p><p><span>4. Brand Reputation: As a trusted brand, we operate with integrity and strive to exceed customer expectations. Over the years, we’ve earned an excellent reputation and high client recognition.&nbsp;&nbsp;</span></p><p><span><br/></span></p><p><span><strong>Applications</strong></span></p><p><span>Our product is applicable to various scenarios and user groups, whether for individual consumers or corporate clients. Regardless of your needs, it delivers outstanding performance and dependable service tailored to diverse requirements.&nbsp;&nbsp;</span></p><p><span><br/></span></p><p><span><strong>Conclusion</strong></span></p><p><span>Thank you for your attention and trust in our product. We will continue to innovate, offering better products and services while surpassing expectations to bring users more surprises and value. If you have any questions or need further details, please feel free to contact us—we are dedicated to serving you wholeheartedly.&nbsp;&nbsp;</span></p><p><span>We hope this introduction provides a deeper understanding of our product and sparks your interest. We look forward to future collaboration!</span></p><p><br/></p>','tuw5cdr.file',NULL,'','0','0','ipad,平板电脑','','50','1','2013-06-26 19:01:52');
