INSERT INTO dou_product VALUES('34','3','admin','0','0','Product Name Demo','','99.00','','0.00',NULL,NULL,'100','<p><span  ><strong>Product Overview&nbsp;</strong></span></p><p><span  >We are honored to introduce our company’s latest product. This product has been meticulously developed and designed to meet consumer needs and deliver a high-quality experience. Below, we will detail its features, functions, advantages, and applications to provide you with a comprehensive understanding.&nbsp;&nbsp;</span></p><p><span  ><br/></span></p><p><span  ><strong>Product Features&nbsp;&nbsp;</strong></span></p><p><span  >1. Innovative Design: Our product emphasizes innovation, combining a unique exterior design with advanced technological applications to ensure it stands out from the competition.&nbsp;&nbsp;</span></p><p><span  >2. Outstanding Performance: We are committed to delivering exceptional performance. Whether in speed, stability, or longevity, our product offers an unparalleled experience.&nbsp;&nbsp;</span></p><p><span  >3. High-Quality Materials: Premium materials are used in manufacturing to guarantee durability and reliability. The product boasts not only an appealing appearance but also superior functionality.&nbsp;&nbsp;</span></p><p><span  >4. User-Centric Design: We prioritize user needs and habits, crafting designs that align with real-world usage. With intuitive operation and comprehensive features, it effortlessly meets user demands.&nbsp;&nbsp;</span></p><p><span  ><br/></span></p><p><span  ><strong>Product Functions</strong></span></p><p><span  >Our product excels with the following features:&nbsp;&nbsp;</span></p><p><span  >1. XXX Function: Leveraging cutting-edge technology, our product achieves the XXX function, providing users with convenient and efficient solutions.&nbsp;&nbsp;</span></p><p><span  >2. XXX Function: Equipped with the XXX function, optimized design and superior performance ensure precise and stable user experiences.&nbsp;&nbsp;</span></p><p><span  >3. XXX Function: Beyond the above, we’ve incorporated the XXX function to cater to diverse user needs and expectations.&nbsp;&nbsp;</span></p><p><span  ><br/></span></p><p><span  ><strong>Product Advantages</strong></span></p><p><span  >1. High Cost-Effectiveness: Our product offers exceptional value in the market. While reasonably priced, it compromises neither quality nor performance.&nbsp;&nbsp;</span></p><p><span  >2. Premium Service: We provide comprehensive after-sales support to ensure your satisfaction. From warranties to technical assistance, we stand by you at every step.&nbsp;&nbsp;</span></p><p><span  >3. Reliability: User experience drives our rigorous quality testing, ensuring reliability and stability in every product.&nbsp;&nbsp;</span></p><p><span  >4. Brand Reputation: As a trusted brand, we operate with integrity and strive to exceed customer expectations. Over the years, we’ve earned an excellent reputation and high client recognition.&nbsp;&nbsp;</span></p><p><span  ><br/></span></p><p><span  ><strong>Applications</strong></span></p><p><span  >Our product is applicable to various scenarios and user groups, whether for individual consumers or corporate clients. Regardless of your needs, it delivers outstanding performance and dependable service tailored to diverse requirements.&nbsp;&nbsp;</span></p><p><span  ><br/></span></p><p><span  ><strong>Conclusion</strong></span></p><p><span  >Thank you for your attention and trust in our product. We will continue to innovate, offering better products and services while surpassing expectations to bring users more surprises and value. If you have any questions or need further details, please feel free to contact us—we are dedicated to serving you wholeheartedly.&nbsp;&nbsp;</span></p><p><span  >We hope this introduction provides a deeper understanding of our product and sparks your interest. We look forward to future collaboration!</span></p><p><br/></p>','z8n8uuv.file',NULL,'','0','0','','','50','1','2025-04-09 21:06:04');
INSERT INTO dou_product VALUES('35','3','admin','0','4','Product Name Demo','','60.00','','0.00',NULL,NULL,'0','**Product Overview** \r\n\r\nWe are honored to introduce our company’s latest product. This product has been meticulously developed and designed to meet consumer needs and deliver a high-quality experience. Below, we will detail its features, functions, advantages, and applications to provide you with a comprehensive understanding.\r\n\r\n**Product Features** \r\n\r\n1. Innovative Design: Our product emphasizes innovation, combining a unique exterior design with advanced technological applications to ensure it stands out from the competition.\r\n2. Outstanding Performance: We are committed to delivering exceptional performance. Whether in speed, stability, or longevity, our product offers an unparalleled experience.\r\n3. High-Quality Materials: Premium materials are used in manufacturing to guarantee durability and reliability. The product boasts not only an appealing appearance but also superior functionality.\r\n4. User-Centric Design: We prioritize user needs and habits, crafting designs that align with real-world usage. With intuitive operation and comprehensive features, it effortlessly meets user demands.\r\n\r\n**Product Functions**\r\n\r\nOur product excels with the following features:\r\n\r\n1. XXX Function: Leveraging cutting-edge technology, our product achieves the XXX function, providing users with convenient and efficient solutions.\r\n2. XXX Function: Equipped with the XXX function, optimized design and superior performance ensure precise and stable user experiences.\r\n3. XXX Function: Beyond the above, we’ve incorporated the XXX function to cater to diverse user needs and expectations.\r\n\r\n**Product Advantages**\r\n\r\n1. High Cost-Effectiveness: Our product offers exceptional value in the market. While reasonably priced, it compromises neither quality nor performance.\r\n2. Premium Service: We provide comprehensive after-sales support to ensure your satisfaction. From warranties to technical assistance, we stand by you at every step.\r\n3. Reliability: User experience drives our rigorous quality testing, ensuring reliability and stability in every product.\r\n4. Brand Reputation: As a trusted brand, we operate with integrity and strive to exceed customer expectations. Over the years, we’ve earned an excellent reputation and high client recognition.\r\n\r\n**Applications**\r\n\r\nOur product is applicable to various scenarios and user groups, whether for individual consumers or corporate clients. Regardless of your needs, it delivers outstanding performance and dependable service tailored to diverse requirements.\r\n\r\n**Conclusion**\r\n\r\nThank you for your attention and trust in our product. We will continue to innovate, offering better products and services while surpassing expectations to bring users more surprises and value. If you have any questions or need further details, please feel free to contact us—we are dedicated to serving you wholeheartedly.\r\n\r\nWe hope this introduction provides a deeper understanding of our product and sparks your interest. We look forward to future collaboration!\r\n','oa2ywjc.file',NULL,'','0','0','','','50','1','2025-04-09 21:06:17');

DROP TABLE IF EXISTS `dou_product_category`;
CREATE TABLE `dou_product_category` (
  `id` smallint(5) NOT NULL AUTO_INCREMENT COMMENT '分类ID',
  `slug` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'URL标识',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分类名称',
  `icon` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '分类图标',
  `keywords` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'SEO关键词',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT 'SEO描述',
  `parent_id` smallint(5) NOT NULL DEFAULT '0' COMMENT '父分类ID',
  `sync_to_nav` tinyint(1) unsigned NOT NULL DEFAULT '1' COMMENT '同步至导航:1是,0否',
  `sort` tinyint(4) unsigned NOT NULL DEFAULT '50' COMMENT '排序',
  PRIMARY KEY (`id`),
  KEY `idx_slug` (`slug`),
  KEY `idx_parent` (`parent_id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

