DROP TABLE IF EXISTS `dou_user`;
CREATE TABLE `dou_user` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '会员ID',
  `user_sn` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '会员编号(唯一)',
  `level_id` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '会员等级ID',
  `distribution_level_id` int(10) unsigned NOT NULL DEFAULT '0',
  `direct_user_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '直接推荐人ID',
  `indirect_user_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '间接推荐人ID',
  `mobile` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email` varchar(180) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `password` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `token` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '登录令牌',
  `token_expires_at` datetime DEFAULT NULL,
  `reset_token` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '密码重置令牌',
  `reset_token_expires_at` datetime DEFAULT NULL,
  `sex` tinyint(1) unsigned NOT NULL DEFAULT '1' COMMENT '性别:1男,0女',
  `nickname` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '昵称',
  `avatar` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `pay_code` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '支付密码',
  `pay_code_updated_at` datetime DEFAULT NULL,
  `login_count` smallint(6) unsigned NOT NULL DEFAULT '0' COMMENT '登录次数',
  `connect_key` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `login_fail_count` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '登录失败次数',
  `login_locked_at` datetime DEFAULT NULL,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active' COMMENT '账号状态:active/suspended/deactivated',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `user_sn` (`user_sn`),
  UNIQUE KEY `email` (`email`),
  UNIQUE KEY `mobile` (`mobile`),
  KEY `idx_pay_code` (`pay_code`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

