DROP TABLE IF EXISTS `dou_user_contact`;
CREATE TABLE `dou_user_contact` (
  `id` mediumint(8) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `user_id` mediumint(8) unsigned NOT NULL DEFAULT '0' COMMENT '会员ID',
  `name` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '联系人姓名',
  `first_name` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `last_name` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `phone` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '手机号',
  `id_card` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '身份证号',
  `province` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '省份',
  `city` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '城市',
  `district` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '区/县',
  `address` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '详细地址',
  `postcode` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `tag` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '标签(如:家人/同事)',
  `is_default` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '是否默认:1是,0否',
  `sort` tinyint(1) unsigned NOT NULL DEFAULT '50' COMMENT '排序',
  `created_at` datetime DEFAULT NULL,
  `country` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  KEY `idx_contact_user` (`user_id`,`is_default`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

