DROP TABLE IF EXISTS `dou_user_level`;
CREATE TABLE `dou_user_level` (
  `id` mediumint(8) unsigned NOT NULL AUTO_INCREMENT COMMENT '等级ID',
  `name` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '等级名称',
  `upgrade_type` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'noauto' COMMENT '升级类型:noauto手动,shopping按消费',
  `upgrade_condition` decimal(10,2) unsigned NOT NULL DEFAULT '100.00' COMMENT '升级条件值',
  `good_discount` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '商品折扣',
  `icon` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '等级图标',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `dou_user_level_log`;
CREATE TABLE `dou_user_level_log` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `user_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `old_level_id` mediumint(8) unsigned NOT NULL DEFAULT '0' COMMENT '旧等级ID',
  `new_level_id` mediumint(8) unsigned NOT NULL DEFAULT '0' COMMENT '新等级ID',
  `upgrade_type` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '升级类型',
  `condition_value` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '触发条件的金额',
  `order_sn` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '触发订单号（如果有）',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  KEY `created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `dou_user_log`;
CREATE TABLE `dou_user_log` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `user_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '用户ID，0表示未登录或不存在',
  `action` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '操作类型，如 login_fail, password_reset, email_change 等',
  `ip` varchar(45) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '操作IP，支持IPv6',
  `created_at` datetime DEFAULT NULL,
  `result` tinyint(1) NOT NULL DEFAULT '0' COMMENT '结果：0失败，1成功（可选）',
  `details` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '额外信息，如失败原因等',
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  KEY `ip` (`ip`),
  KEY `created_at` (`created_at`),
  KEY `action` (`action`(191))
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO dou_user_log VALUES('1','1','[LOGIN_SUCCESS]','127.0.0.1','2026-11-02 13:32:55','1','');

DROP TABLE IF EXISTS `dou_user_sns`;
CREATE TABLE `dou_user_sns` (
  `id` mediumint(8) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `user_id` mediumint(8) unsigned NOT NULL DEFAULT '0' COMMENT '会员ID',
  `group` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '第三方分组(如wxlogin)',
  `openid` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'OpenID',
  `unionid` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'UnionID',
  `apptype` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '应用类型(miniprogram/oa等)',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `openid` (`openid`),
  KEY `idx_sns_user_group` (`user_id`,`group`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `dou_user_tag`;
CREATE TABLE `dou_user_tag` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(10) unsigned NOT NULL,
  `tag` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_user` (`user_id`),
  KEY `idx_tag` (`tag`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `dou_user_token`;
CREATE TABLE `dou_user_token` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `user_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '会员ID',
  `token_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'API会话token的sha256散列',
  `expires_at` datetime DEFAULT NULL,
  `last_active_at` datetime DEFAULT NULL,
  `client_ip` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '签发时客户端IP',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `token_hash` (`token_hash`),
  KEY `user_id` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `dou_user_wallet`;
CREATE TABLE `dou_user_wallet` (
  `id` int(10) unsigned NOT NULL COMMENT '会员ID',
  `money_balance` decimal(12,2) NOT NULL DEFAULT '0.00',
  `money_freeze` decimal(12,2) NOT NULL DEFAULT '0.00',
  `point_balance` int(11) NOT NULL DEFAULT '0',
  `point_freeze` int(11) NOT NULL DEFAULT '0',
  `total_consumption` decimal(12,2) NOT NULL DEFAULT '0.00',
  `total_promote` decimal(12,2) NOT NULL DEFAULT '0.00',
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


